const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}

if (!Array.isArray(body.confirmations) || body.confirmations.length !== 5) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_CONFIRMATIONS', message: 'confirmations must be an array of exactly 5 items - the same 5 shown on the Approval screen.' } }];
}

// Re-checked here, not just trusted from the disabled button on the
// frontend - same belt-and-suspenders principle Approval's own submit
// button already follows (see its own code comment), just enforced
// server-side too, since a disabled button is a UI convenience, not a
// security boundary.
const uncheckedIndices = body.confirmations
  .map(function(c, i) { return { index: i, checked: !!(c && c.checked) }; })
  .filter(function(c) { return !c.checked; })
  .map(function(c) { return c.index; });

if (uncheckedIndices.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'CONFIRMATIONS_INCOMPLETE',
    message: 'All 5 confirmations must be checked before an approval can be logged.',
    unchecked_indices: uncheckedIndices
  }}];
}

if (!body.json_payload || typeof body.json_payload !== 'object') {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_PAYLOAD',
    message: 'json_payload is required - build it via wf24 (existing-parent) or wf27 (new-parent) before calling this.'
  }}];
}

return [{ json: {
  decision: 'VALID',
  request_id: body.request_id,
  approved_by: body.approved_by || 'seller',
  confirmations: body.confirmations,
  parent_content: body.parent_content || null,
  json_payload: body.json_payload
}}];

const validated = $('Validate Input').first().json;
const fetched = $input.first().json;
const row = Array.isArray(fetched) ? fetched[0] : fetched;

if (!row || !row.request_id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MERGE_REQUEST_NOT_FOUND',
    request_id: validated.request_id,
    message: 'No merge_requests row found for this request_id - approval cannot be logged against a request that was never created.'
  }}];
}

// approval_logs already existed in this Supabase project - built during
// the original rebuild plan, before any Gen-2 workflow ever wrote to it,
// and before this screen's confirmations grew from 4 checks to 5. Its 4
// named boolean columns predate that growth. Items 1 and 2 here are both
// about review manipulation/consolidation specifically, so both map onto
// the single confirm_no_review_manipulation column; the other three map
// through 1:1. is_new_parent and the new-parent content aren't stored
// separately - is_new_parent is one join away via request_id, and the
// generated title/bullets/description are already inside json_payload's
// own parent listing patches, so duplicating them here would just be
// storing the same data twice.
const c = validated.confirmations;
const notes = c.map(function(item, i) { return '(' + (i + 1) + ') ' + item.text; }).join(' ');

return [{ json: {
  decision: 'FOUND',
  request_id: row.request_id,
  seller_id: row.seller_id,
  approved_by: validated.approved_by,
  confirm_same_product_family: !!(c[0] && c[0].checked),
  confirm_no_review_manipulation: !!(c[1] && c[1].checked) && !!(c[2] && c[2].checked),
  confirm_matrix_correct: !!(c[3] && c[3].checked),
  confirm_understands_risk: !!(c[4] && c[4].checked),
  notes: notes,
  json_payload: validated.json_payload
}}];

const inserted = $input.first().json;
const row = Array.isArray(inserted) ? inserted[0] : inserted;

if (!row || !row.id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'APPROVAL_LOG_INSERT_FAILED',
    message: 'The approval_logs insert did not return a row.',
    upstream_raw: inserted
  }}];
}

return [{ json: {
  decision: 'APPROVED_AND_LOGGED',
  request_id: row.request_id,
  approval_log_id: row.id,
  // Real column is created_at, not approved_at - this table predates
  // this workflow. Read the real column, still expose it as approved_at
  // here so the frontend's existing contract doesn't need to change too.
  approved_at: row.created_at,
  message: 'Approval logged and the final payload staged. Nothing was sent to Amazon - live submission is still on hold pending Amazon app review.'
}}];
